`timescale 1ns/1ps
module dma_engine_v4 #(parameter int ADDR_WIDTH=48,LEN_WIDTH=20,DATA_WIDTH=64)(input logic clk,rst_n,start,input logic [ADDR_WIDTH-1:0] src_addr,dst_addr,input logic [LEN_WIDTH-1:0] length_bytes,output logic busy,done,error,output logic rd_valid,input logic rd_ready,output logic [ADDR_WIDTH-1:0] rd_addr,input logic rd_rsp_valid,rd_rsp_ready,input logic [DATA_WIDTH-1:0] rd_rdata,output logic wr_valid,input logic wr_ready,output logic [ADDR_WIDTH-1:0] wr_addr,output logic [DATA_WIDTH-1:0] wr_wdata,output logic [DATA_WIDTH/8-1:0] wr_be);typedef enum logic[2:0]{S_IDLE,S_READ_REQ,S_READ_WAIT,S_WRITE,S_DONE}state_t;state_t state;logic[ADDR_WIDTH-1:0]saddr,daddr;logic[LEN_WIDTH-1:0]remaining;logic[DATA_WIDTH-1:0]data_buf;always_comb begin busy=(state!=S_IDLE)&&(state!=S_DONE);done=(state==S_DONE);error=0;rd_valid=(state==S_READ_REQ);rd_addr=saddr;wr_valid=(state==S_WRITE);wr_addr=daddr;wr_wdata=data_buf;wr_be='1;end always_ff@(posedge clk or negedge rst_n)begin if(!rst_n)begin state<=S_IDLE;saddr<='0;daddr<='0;remaining<='0;data_buf<='0;end else case(state)S_IDLE:if(start&&length_bytes!=0)begin saddr<=src_addr;daddr<=dst_addr;remaining<=length_bytes;state<=S_READ_REQ;end S_READ_REQ:if(rd_ready)state<=S_READ_WAIT;S_READ_WAIT:if(rd_rsp_valid&&rd_rsp_ready)begin data_buf<=rd_rdata;state<=S_WRITE;end S_WRITE:if(wr_ready)begin saddr<=saddr+(DATA_WIDTH/8);daddr<=daddr+(DATA_WIDTH/8);if(remaining<=(DATA_WIDTH/8))begin remaining<='0;state<=S_DONE;end else begin remaining<=remaining-(DATA_WIDTH/8);state<=S_READ_REQ;end end S_DONE:state<=S_IDLE;default:state<=S_IDLE;endcase end endmodule
